 let facts=managementFact('Resultado do período',`<span class="management-feature">${fmt(s.rate,'percent')}</span><span class="management-caption">de aproveitamento</span><span class="management-pair"><span>${managementNumber(s[closed])} ${forecast?'readesões':'fechamentos'}</span><span>${managementNumber(s[volume])} ${forecast?'previstos':'atendimentos'}</span></span>`);
