function emphasizeMetrics(root){root.querySelectorAll('.insight-card p,.action-card p').forEach(p=>{const walker=document.createTreeWalker(p,NodeFilter.SHOW_TEXT),nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);nodes.forEach(node=>{const re=/(?:R\$\s*)?[+-]?\d+(?:\.\d{3})*(?:,\d+)?(?:\s*p\.p\.|%)?/g,text=node.nodeValue;if(!re.test(text))return;re.lastIndex=0;const frag=document.createDocumentFragment();let last=0,m;while((m=re.exec(text))){frag.append(document.createTextNode(text.slice(last,m.index)));const strong=document.createElement('strong');strong.className='metric-number'+(m[0].trim().startsWith('+')?' delta-positive':m[0].trim().startsWith('-')?' delta-negative':'');strong.textContent=m[0];frag.append(strong);last=m.index+m[0].length}frag.append(document.createTextNode(text.slice(last)));node.replaceWith(frag)})});emphasizeAnalyticalNumbers(root);highlightActionNames(root);addCopyControls(root)}
