function applyPeriod(key){const d=today(),y=d.getFullYear(),m=d.getMonth();let start,end;if(key==='previousYear'){start=new Date(y-1,0,1);end=new Date(y-1,11,31)}else if(key==='currentYear'){start=new Date(y,0,1);end=new Date(y,11,31)}else if(key==='previousMonth'){start=new Date(y,m-1,1);end=new Date(y,m,0)}else if(key==='currentMonth'){start=new Date(y,m,1);end=new Date(y,m+1,0)}else if(key==='lastThree'){start=new Date(y,m-3,1);end=new Date(y,m,0)}else{state.period=key;updateDateLabels();return}state.start=iso(start);state.end=iso(end);state.period=key;updateDateLabels()}
