function calendar(key,year,month){const date=new Date(year,month,1),selected=state[key],tod=iso(today()),offset=(date.getDay()+6)%7,days=new Date(year,month+1,0).getDate();let html=`<div class="calendar-head"><button data-calnav="-1" data-datekey="${key}" data-year="${year}" data-month="${month}" aria-label="Mês anterior">‹</button><select data-calmonth="${key}" data-year="${year}" aria-label="Mês do calendário">${MONTHS.map((m,i)=>`<option value="${i}" ${i===month?'selected':''}>${m}</option>`).join('')}</select><select data-calyear="${key}" data-month="${month}" aria-label="Ano do calendário">${Array.from({length:Math.max(year+2,today().getFullYear()+2)-2024},(_,i)=>2024+i).map(y=>`<option ${y===year?'selected':''}>${y}</option>`).join('')}</select><button data-calnav="1" data-datekey="${key}" data-year="${year}" data-month="${month}" aria-label="Próximo mês">›</button></div><div class="calendar-grid">${['S','T','Q','Q','S','S','D'].map(d=>`<small>${d}</small>`).join('')}${'<span></span>'.repeat(offset)}`;for(let i=1;i<=days;i++){const value=iso(new Date(year,month,i));html+=`<button class="calendar-day ${value===selected?'selected':''} ${value===tod?'today':''}" data-setdate="${value}" data-datekey="${key}" aria-label="${dateBR(value)}">${i}</button>`}html+=`</div><div class="calendar-manual"><input type="date" value="${selected}" id="${key}Manual" aria-label="Digitar data ${key==='start'?'inicial':'final'}"><button data-manual="${key}">Aplicar</button></div>`;el(key+'Calendar').innerHTML=html;el(key+'Calendar').hidden=false;enhanceSelectMenus(el(key+'Calendar'))}
function download(name,content,type='text/plain'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function highlightActionNames(root){const names=new Map();DATA.conversion.forEach(r=>{if(r.person){const label=personClinicLabel(r.person,r.clinic,r.dimension);names.set(label,CLINICS[r.clinic]?.color||'#1597ed')}});root.querySelectorAll('.action-card p').forEach(p=>{const walker=document.createTreeWalker(p,NodeFilter.SHOW_TEXT),nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);nodes.forEach(node=>{let text=node.nodeValue;const matches=[...names].filter(([name])=>text.includes(name));if(!matches.length)return;const frag=document.createDocumentFragment();while(text.length){let match=null;matches.forEach(([name,color])=>{const index=text.indexOf(name);if(index>=0&&(!match||index<match.index))match={name,color,index}});if(!match){frag.append(document.createTextNode(text));break}frag.append(document.createTextNode(text.slice(0,match.index)));const strong=document.createElement('strong');strong.className='action-person';strong.style.setProperty('--clinic',match.color);strong.textContent=match.name;frag.append(strong);text=text.slice(match.index+match.name.length)}node.replaceWith(frag)})})}
function addCopyControls(root){root.querySelectorAll('.clinic-card,.insight-card,.action-card,.professional-highlight,.executive-strip').forEach((card,i)=>{if(card.querySelector(':scope > .copy-control'))return;if(!card.id)card.id=`copy-card-${state.area}-${state.tab}-${i}`;const button=document.createElement('button');button.className='copy-control';button.type='button';button.dataset.copyTarget=card.id;button.title='Copiar este cartão como imagem';button.setAttribute('aria-label','Copiar este cartão como imagem');button.textContent='⧉';card.append(button)})}
