 await document.fonts.ready;
 const rect=target.getBoundingClientRect(),width=Math.ceil(Math.max(rect.width,target.scrollWidth)),height=Math.ceil(Math.max(rect.height,target.scrollHeight)),pad=16,scale=Math.min(2,14000/(height+pad*2),Math.sqrt(24000000/((width+pad*2)*(height+pad*2)))),clone=target.cloneNode(true);
 clone.querySelectorAll('.copy-control,.panel-actions,.table-actions,.panel-expand,.kpi-copy-menu,.kpi-copy-toolbar').forEach(n=>n.remove());
 clone.style.width=width+'px';clone.style.height='auto';clone.style.margin='0';clone.style.transform='none';
 clone.querySelectorAll('th,td').forEach(n=>n.style.position='static');
 const ns='http://www.w3.org/2000/svg',htmlns='http://www.w3.org/1999/xhtml',svg=document.createElementNS(ns,'svg'),foreign=document.createElementNS(ns,'foreignObject'),wrap=document.createElementNS(htmlns,'div'),style=document.createElementNS(htmlns,'style');
 const W=width+pad*2,H=height+pad*2;svg.setAttribute('width',Math.ceil(W*scale));svg.setAttribute('height',Math.ceil(H*scale));svg.setAttribute('viewBox',`0 0 ${W} ${H}`);foreign.setAttribute('width',W);foreign.setAttribute('height',H);
 wrap.className='snapshot-shell '+(document.body.classList.contains('dark')?'dark':'');wrap.style.cssText=`padding:${pad}px;width:${W}px;height:${H}px;background:${getComputedStyle(document.body).getPropertyValue('--paper')||'#fff'};font-family:Prompt,Arial,sans-serif;box-sizing:border-box`;
 const rootStyle=getComputedStyle(document.documentElement);for(let i=0;i<rootStyle.length;i++){const key=rootStyle[i];if(key.startsWith('--'))wrap.style.setProperty(key,rootStyle.getPropertyValue(key))}
 style.textContent=[...document.querySelectorAll('style')].map(n=>n.textContent).join('\n')+'\n.snapshot-shell *{animation:none!important;transition:none!important}.snapshot-shell .kpi,.snapshot-shell .panel,.snapshot-shell .clinic-card,.snapshot-shell .insight-card{transform:none!important}.snapshot-shell .table-scroll{overflow:visible!important;max-height:none!important}.snapshot-shell .copy-control{display:none!important}.snapshot-shell .analysis-options{display:none!important}';
 wrap.append(style,clone);foreign.append(wrap);svg.append(foreign);
 const xml=new XMLSerializer().serializeToString(svg),url='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(xml),image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(new Error('Falha na geração da imagem do cartão'));image.src=url});
 const canvas=document.createElement('canvas');canvas.width=Math.ceil(W*scale);canvas.height=Math.ceil(H*scale);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);return await new Promise((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(new Error('Não foi possível criar a imagem PNG')),'image/png'));
