document.addEventListener('input',e=>{const input=e.target;if(!input.dataset.tableSearch)return;const table=el(input.dataset.tableSearch);if(!table)return;const q=input.value.trim().toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'');let visible=0;[...table.tBodies[0].rows].forEach(row=>{const text=row.textContent.toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'');row.hidden=!!q&&!text.includes(q);if(!row.hidden)visible++});const count=document.querySelector(`[data-table-count="${input.dataset.tableSearch}"]`);if(count)count.textContent=q?`${fmt(visible)} de ${fmt(table.tBodies[0].rows.length)} grupos visíveis · O total no rodapé considera o filtro completo.`:`${fmt(table.tBodies[0].rows.length)} grupos no período · O total no rodapé considera o filtro completo.`});
