function positionTooltip(target,tip){const r=target.getBoundingClientRect(),gap=12,pad=12;if(target.matches('.kpi')){const top=r.bottom+gap;tip.style.maxHeight=Math.max(70,innerHeight-top-pad)+'px';tip.style.left=Math.max(pad,Math.min(innerWidth-tip.offsetWidth-pad,r.left+(r.width-tip.offsetWidth)/2))+'px';tip.style.top=top+'px';return}tip.style.maxHeight='min(72vh,620px)';const w=tip.offsetWidth,h=tip.offsetHeight;let left=r.right+gap;if(left+w>innerWidth-pad)left=r.left-w-gap;if(left<pad)left=Math.max(pad,Math.min(innerWidth-w-pad,r.left+(r.width-w)/2));const top=Math.max(pad,Math.min(r.top,innerHeight-h-pad));tip.style.left=left+'px';tip.style.top=top+'px'}

function miniTrend(series,expanded=false){
 const values=series.months.filter(m=>Number.isFinite(m.value));if(!values.length)return '<p class="mini-empty">Sem valores mensais neste indicador.</p>';
 const W=expanded?900:380,H=expanded?330:165,L=expanded?65:38,R=expanded?65:38,T=36,B=30,color=series.color||'#1597ed',lo=Math.min(...values.map(m=>m.value)),hi=Math.max(...values.map(m=>m.value)),span=hi-lo||Math.max(1,Math.abs(hi)*.15),x=i=>L+(values.length===1?(W-L-R)/2:i*(W-L-R)/(values.length-1)),y=v=>T+(H-T-B)*(1-(v-lo)/span),points=values.map((m,i)=>`${x(i)},${y(m.value)}`).join(' '),path=`M ${values.map((m,i)=>`${x(i)} ${y(m.value)}`).join(' L ')}`,area=`${path} L ${x(values.length-1)} ${H-B} L ${x(0)} ${H-B} Z`;
 return `<svg class="mini-trend ${expanded?'large-trend':''}" style="--series-color:${color}" viewBox="0 0 ${W} ${H}" role="img" aria-label="Evolução mensal de ${safe(series.metric)}"><path d="${area}" fill="${color}" fill-opacity=".07"/><polyline points="${points}" fill="none" stroke="${color}" stroke-width="${expanded?3:2.5}" stroke-linecap="round" stroke-linejoin="round"/>${values.map((m,i)=>`<g ${expanded?`data-tip="${safe(JSON.stringify([{label:series.metric,value:m.value,type:series.type,color}]))}" data-tip-title="${safe(series.label)} · ${MONTHS[m.month-1]} ${m.year}"`:''}><circle cx="${x(i)}" cy="${y(m.value)}" r="${expanded?5:3.5}" fill="${color}" stroke="var(--paper)" stroke-width="2"/><text class="trend-data-label" x="${x(i)}" y="${Math.max(14,y(m.value)-12)}" text-anchor="middle" fill="${color}" font-size="${expanded?12:8}" font-weight="800">${fmt(m.value,series.type)}</text></g>`).join('')}${values.map((m,i)=>`<text x="${x(i)}" y="${H-6}" text-anchor="middle" fill="var(--ink)" font-size="${expanded?12:8}" font-weight="800">${MONTHS[m.month-1].slice(0,3).toLocaleUpperCase('pt-BR')}</text>`).join('')}</svg>`
}
function monthVariations(series){return `<div class="month-variations"><div class="variation-heading">VARIAÇÃO ENTRE MESES <small>Diferença em relação ao mês anterior disponível</small></div><div class="variation-grid">${series.months.slice(1).map((m,i)=>{const prev=series.months[i],valid=Number.isFinite(m.value)&&Number.isFinite(prev.value),gap=m.year*12+m.month-(prev.year*12+prev.month),d=valid&&gap===1?m.value-prev.value:null,cls=d>0?'delta-positive':d<0?'delta-negative':'delta-neutral';return `<div class="month-change"><span>${MONTHS[prev.month-1].slice(0,3).toUpperCase()} → ${MONTHS[m.month-1].slice(0,3).toUpperCase()}</span><b class="${cls}">${d==null?'Sem mês consecutivo':`${d>0?'+':''}${fmt(d,series.type==='percent'?'decimal':series.type)}${series.type==='percent'?' p.p.':''}`}</b><small>${d==null?'Intervalo sem registro':d>0?'Aumento':d<0?'Redução':'Sem variação'}</small></div>`}).join('')}</div></div>`}
function addExpandedLabels(visual){visual.querySelectorAll('rect[data-chart-value]').forEach(rect=>{const value=+rect.dataset.chartValue;if(!value)return;const g=rect.parentElement;g.querySelectorAll('text:not(.expanded-data-label)').forEach(t=>{if(!/[A-Z]{3}/.test(t.textContent))t.remove()});const text=document.createElementNS('http://www.w3.org/2000/svg','text');text.classList.add('expanded-data-label');text.setAttribute('x',+rect.getAttribute('x')+(+rect.getAttribute('width'))/2);text.setAttribute('y',Math.max(14,+rect.getAttribute('y')-7));text.setAttribute('text-anchor','middle');text.setAttribute('fill',rect.dataset.chartColor||'var(--ink)');text.setAttribute('font-size','9');text.setAttribute('font-weight','800');text.textContent=fmt(value);g.append(text)})}

function showTooltip(target){const tip=el('tooltip');if(activeTooltipTarget===target&&!tip.hidden)return;clearTimeout(tooltipHideTimer);activeTooltipTarget=target;let content;if(target.dataset.monthSeries){const s=JSON.parse(target.dataset.monthSeries);content=`<div class="tip-trend-head"><span class="tip-kicker">EVOLUÇÃO NO PERÍODO</span><b>${safe(s.label)}</b><small>${safe(s.metric)}</small></div>${miniTrend(s)}<p class="tip-pin-hint">Clique em uma célula para fixar este painel. Pressione Esc para liberar.</p>${pinnedTooltip?`<button class="tip-expand-action tip-unpin" data-unpin-tooltip>Desafixar tooltip</button>`:''}<button class="tip-expand-action" data-expand-series="${safe(JSON.stringify(s))}">Ampliar evolução <span>↗</span></button>`}else{const items=JSON.parse(target.dataset.tip).sort((a,b)=>(b.value??-1)-(a.value??-1));content=`<b class="tip-title">${target.dataset.tipColor?`<i class="dot" style="--clinic:${safe(target.dataset.tipColor)}"></i>`:''}${safe(target.dataset.tipTitle)}</b>${items.map(d=>`<div class="tooltip-row"><span class="tip-label">${d.color?`<i class="dot" style="--clinic:${safe(d.color)}"></i>`:''}${safe(d.label)}</span><span class="tip-values"><strong>${fmt(d.value,d.type)}${d.share!==undefined?`<span class="tip-percentage">${fmt(d.share,'percent')}</span>`:''}</strong>${d.detail?`<small>${safe(d.detail)}</small>`:''}</span></div>`).join('')}`}tip.innerHTML=content;tip.hidden=false;tip.style.visibility='hidden';positionTooltip(target,tip);tip.style.visibility='visible'}
document.addEventListener('pointermove',e=>{if(pinnedTooltip){if(e.target.closest('#tooltip'))clearTimeout(tooltipHideTimer);return}const target=e.target.closest('[data-tip],[data-month-series]');if(target){showTooltip(target);return}if(e.target.closest('#tooltip')){clearTimeout(tooltipHideTimer);return}scheduleTooltipHide()});
el('tooltip').addEventListener('pointerenter',()=>clearTimeout(tooltipHideTimer));el('tooltip').addEventListener('pointerleave',scheduleTooltipHide);
document.addEventListener('click',e=>{const source=e.target.closest('[data-month-series]'),expand=e.target.closest('[data-expand-series]'),unpin=e.target.closest('[data-unpin-tooltip]');if(unpin){pinnedTooltip=false;el('tooltip').hidden=true;return}if(source){pinnedTooltip=activeTooltipTarget!==source||!pinnedTooltip;activeTooltipTarget=null;showTooltip(source);return}if(expand){const s=JSON.parse(expand.dataset.expandSeries),dialog=el('visualModal');el('visualContent').innerHTML=`<span class="view-kicker">EVOLUÇÃO MENSAL · ${safe(s.metric)}</span><h2>${safe(s.label)}</h2><p>Valores mensais dentro do período e dos filtros aplicados.</p><div class="expanded-mini-trend">${miniTrend(s,true)}${monthVariations(s)}</div>`;pinnedTooltip=false;activeTooltipTarget=null;el('tooltip').hidden=true;dialog.showModal();dialog.querySelector('.visual-modal-head').append(el('tooltip'));return}if(pinnedTooltip&&!e.target.closest('#tooltip')){pinnedTooltip=false;el('tooltip').hidden=true;activeTooltipTarget=null}});
document.addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)&&e.target.matches('[data-month-series]')){pinnedTooltip=true;activeTooltipTarget=null;showTooltip(e.target)}if(e.key==='Escape')pinnedTooltip=false});
el('visualModal').addEventListener('close',()=>{document.body.append(el('tooltip'));el('tooltip').hidden=true;pinnedTooltip=false;activeTooltipTarget=null});
window.addEventListener('scroll',()=>{el('backTop').hidden=scrollY<450;el('tooltip').hidden=true;pinnedTooltip=false;activeTooltipTarget=null},{passive:true});
try{if(localStorage.getItem('alfamen-conversao-theme')==='dark'){document.body.classList.add('dark');updateThemeButton()}}catch{}
applyPeriod('currentYear');render();
